package javapractice;

public class LoopDemo {

	public void printtable() {
		for(int i=1;i<=10; i++)
		{
			System.out.println(i*3); 
		}
	}
		
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		LoopDemo ob=new LoopDemo();
		ob.printtable(); 
	}

}
